<script setup lang="ts">
import{ref,computed,onMounted,onBeforeUnmount}from'vue';import{useRoute,onBeforeRouteLeave}from'vue-router';
import{NButton,NInput,NInputNumber,NSelect,NTag,NAlert,NFormItem,NTabs,NTab,NCheckbox,NEmpty,useMessage,useDialog}from'naive-ui';
import{kindLabels,kinds,type DocumentKind,type ContestDataValue}from'@problemforge/contracts';
import{useTaskEvents}from'../task-events';
import{api}from'../api';import MemberPanel from'../components/MemberPanel.vue';import PackagePanel from'../components/PackagePanel.vue';import PdfPreview from'../components/PdfPreview.vue';
import EditorFeedback from '../components/EditorFeedback.vue';
import SourceEditor from '../components/SourceEditor.vue';
import ContestIntroductionAssets from '../components/ContestIntroductionAssets.vue';
import { snapshot, mergeSaved, downloadDraft } from '../draft-state';
import { rememberedChoice, useUnsavedGuard } from '../editor-navigation';
const route=useRoute(),message=useMessage(),dialog=useDialog(),contest=ref<any>(),data=ref<ContestDataValue>(),dirty=ref(false),busy=ref(false),tab=rememberedChoice('contest-tab','arrange',['arrange','materials','members','packages']),saveError=ref('');
const problems=ref<any[]>([]),templates=ref<any[]>([]),problemId=ref<string|null>(null),syncError=ref('');
const revisionId=ref('LATEST'),bundles=ref<any[]>([]),selectedBuild=ref<any>(),releases=ref<any[]>([]),buildTab=ref('preview'),subset=ref<string[]>([]),useSubset=ref(false),missing=ref<any[]>([]);
const writable=computed(()=>['OWNER','EDITOR'].includes(contest.value?.role));
const chosenFrozen=computed(()=>contest.value?.revisions.find((r:any)=>r.id===revisionId.value));
const selectedItems=computed(()=>contest.value?.completeness.items??[]);
const materialItems=computed(()=>chosenFrozen.value?.items??selectedItems.value);
const introductionLength=computed(()=>data.value?.beamerIntroduction?.length??0);
const introductionTooLong=computed(()=>introductionLength.value>40000);
const introductionExample=String.raw`\begin{frame}{比赛总结}
\begin{itemize}
  \item 本场比赛的设计思路与题目安排。
  \item 希望分享的亮点、经验与感谢。
\end{itemize}
\end{frame}`;

function changed(){dirty.value=true;}
function updateIntroduction(value:string){if(!writable.value||!data.value)return;data.value.beamerIntroduction=value;changed();}
function insertIntroductionImage(frame:string){if(!writable.value||!data.value)return;const current=data.value.beamerIntroduction??'';const next=current+`${current?'\n\n':''}${frame}\n`;if(next.length>40000){message.error('插入后开场总结将超过 40,000 字，请先缩短内容；图片已保留，可稍后插入');return;}updateIntroduction(next);message.success('图片页已追加到开场总结末尾，请保存编排');}
useUnsavedGuard(()=>dirty.value||busy.value);
async function act(fn:()=>Promise<void>){busy.value=true;try{await fn();}catch(e){message.error((e as Error).message);if((e as any).code==='MISSING_MATERIAL')missing.value=(e as any).details??[];}finally{busy.value=false;}}
async function results(){bundles.value=await api(`/contests/${route.params.id}/builds`);releases.value=await api(`/contests/${route.params.id}/releases`);if(selectedBuild.value)await inspect(selectedBuild.value.id);}
async function load(){contest.value=await api(`/contests/${route.params.id}`);data.value=JSON.parse(JSON.stringify(contest.value.data));dirty.value=false;await results();}
let refreshing=false,refreshTimer:ReturnType<typeof setInterval>|undefined;
async function refreshSources(){const updated:any=await api(`/contests/${route.params.id}`);if(!contest.value)return;contest.value.completeness=updated.completeness;contest.value.revisions=updated.revisions;}
async function refreshCurrent(){if(!contest.value||busy.value||refreshing||document.hidden)return;refreshing=true;try{await refreshSources();await results();syncError.value='';}catch(e){syncError.value=(e as Error).message;}finally{refreshing=false;}}
onMounted(()=>{void act(async()=>{await load();problems.value=await api('/problems');templates.value=await api('/templates');});window.addEventListener('focus',refreshCurrent);refreshTimer=setInterval(refreshCurrent,10000);});
onBeforeUnmount(()=>{window.removeEventListener('focus',refreshCurrent);clearInterval(refreshTimer);});
useTaskEvents(()=>results().catch(e=>message.error(e.message)),{contestId:String(route.params.id)});
function add(){if(!problemId.value||!data.value)return;data.value.items.push({problemId:problemId.value,code:String.fromCharCode(65+data.value.items.length),lectureOrder:data.value.items.length+1,expectedDifficulty:''});changed();problemId.value=null;}
function move(i:number,delta:number){const items=data.value!.items;[items[i],items[i+delta]]=[items[i+delta],items[i]];changed();}
async function save(){if(busy.value||!data.value||introductionTooLong.value)return;busy.value=true;saveError.value='';const submitted=snapshot(data.value);try{const saved=await api(`/contests/${route.params.id}`,{method:'PUT',body:JSON.stringify({expectedVersion:contest.value.version,data:submitted})});data.value=mergeSaved(data.value,submitted,saved.data);dirty.value=JSON.stringify(data.value)!==JSON.stringify(saved.data);Object.assign(contest.value,saved);const updated=await api(`/contests/${route.params.id}`);contest.value.completeness=updated.completeness;contest.value.revisions=updated.revisions;message.success(dirty.value?'已保存提交时的编排；继续输入的修改仍未保存':'编排已保存；既有冻结清单保留');}catch(e){saveError.value=(e as Error).message;message.error(saveError.value);}finally{busy.value=false;}}
async function freeze(){if(dirty.value||busy.value)return;await act(async()=>{const r=await api(`/contests/${route.params.id}/freeze`,{method:'POST',body:JSON.stringify({expectedVersion:contest.value.version})});revisionId.value='LATEST';await refreshSources();tab.value='materials';message.success(`已冻结比赛版本 #${r.number}`);});}
async function build(selectedKinds:DocumentKind[]){if(dirty.value||busy.value)return;missing.value=[];await act(async()=>{const r=await api(`/contests/${route.params.id}/builds`,{method:'POST',body:JSON.stringify({...(revisionId.value==='LATEST'?{expectedVersion:contest.value.version}:{revisionId:revisionId.value}),kinds:selectedKinds,...(useSubset.value?{subset:subset.value}:{})})});await refreshSources();await results();await inspect(r.builds[0].id);buildTab.value='log';});}
async function inspect(id:string){const b=await api(`/builds/${id}`);const row=bundles.value.flatMap(b=>b.builds).find(b=>b.id===id);selectedBuild.value={...b,stale:row?.stale??false};}
async function taskAction(action:'cancel'|'retry'){await act(async()=>{const r=await api(`/builds/${selectedBuild.value.id}/${action}`,{method:'POST'});await results();if(action==='retry')await inspect(r.id);});}
function publish(){dialog.warning({title:`公开发布${kindLabels[selectedBuild.value.kind as DocumentKind]}`,content:'只发布选中的 PDF。若为显式子集，文件仅包含选中的题目；其他资料保留各自的发布状态。',positiveText:'发布此 PDF',negativeText:'返回',onPositiveClick:()=>act(async()=>{await api(`/contests/${route.params.id}/releases`,{method:'POST',body:JSON.stringify({buildId:selectedBuild.value.id})});await results();})});}
async function revoke(id:string){await act(async()=>{await api(`/releases/${id}/revoke`,{method:'POST'});await results();});}
function templateOptions(kind:DocumentKind){return templates.value.filter(t=>t.template.kind===kind&&t.contestCapable&&t.languages.includes(data.value!.language)).map(t=>({label:`${t.template.name} · v${t.number}`,value:t.id}));}
function itemTitle(item:{problemId:string}){return selectedItems.value.find((p:any)=>p.problemId===item.problemId)?.title??problems.value.find(p=>p.id===item.problemId)?.title??item.problemId;}
</script>
<template><template v-if="contest&&data"><EditorFeedback :dirty="dirty" :saving="busy" :error="saveError" :version="contest.version" label="比赛编排" @export="downloadDraft(`contest-${contest.id}`,{id:contest.id,baseVersion:contest.version,data})"/><div class="workspace-heading"><div><div class="breadcrumb"><RouterLink to="/contests">比赛</RouterLink> / 工作区</div><h1>{{contest.title}}</h1></div><NTag>{{contest.role}} · 编排 v{{contest.version}}{{dirty?' · 未保存':''}}</NTag></div><div class="panel p4-panel"><NTabs v-model:value="tab"><NTab name="arrange">比赛编排</NTab><NTab name="materials">冻结与资料</NTab><NTab name="packages">题包与发布</NTab><NTab name="members">成员与权限</NTab></NTabs>
<div v-if="tab==='arrange'"><div class="p4-form-row"><NFormItem label="比赛名称"><NInput v-model:value="data.title" :disabled="!writable" @update:value="changed"/></NFormItem><NFormItem label="署名"><NInput v-model:value="data.author" :disabled="!writable" @update:value="changed"/></NFormItem><NFormItem label="语言"><NInput v-model:value="data.language" :disabled="!writable" @update:value="changed"/></NFormItem></div><div class="p4-form-row"><NFormItem label="场次"><NInput v-model:value="data.stage" :disabled="!writable" @update:value="changed"/></NFormItem><NFormItem label="页眉日期"><NInput v-model:value="data.dateHeader" :disabled="!writable" @update:value="changed"/></NFormItem><NFormItem label="封面日期"><NInput v-model:value="data.dateCover" :disabled="!writable" @update:value="changed"/></NFormItem></div><div class="p4-form-row"><NFormItem v-for="k in kinds" :key="k" :label="`${kindLabels[k]}模板（固定版本）`"><NSelect v-model:value="data.templates[k]" :options="templateOptions(k)" clearable :disabled="!writable" @update:value="changed"/></NFormItem></div>
<div v-if="writable" class="p4-toolbar"><NSelect v-model:value="problemId" :options="problems.filter(p=>!data!.items.some(i=>i.problemId===p.id)).map(p=>({label:p.title,value:p.id}))" filterable placeholder="选择有权访问的源题"/><NButton :disabled="!problemId||busy" @click="add">加入比赛</NButton></div>
<div class="contest-items-scroll"><table class="data-table"><thead><tr><th>题号</th><th>题目 / 内容同步</th><th>预计难度</th><th>Beamer 讲解顺序</th><th>题册顺序</th></tr></thead><tbody><tr v-for="(item,i) in data.items" :key="item.problemId"><td><NInput v-model:value="item.code" :disabled="!writable" style="width:85px" @update:value="changed"/></td><td>{{itemTitle(item)}}<small>自动同步最新已保存内容</small></td><td><NInput v-model:value="item.expectedDifficulty" :disabled="!writable" :maxlength="40" placeholder="如：入门 / 1800" :input-props="{'aria-label':`${item.code} 预计难度`}" class="contest-difficulty-input" @update:value="changed"/></td><td><NInputNumber v-model:value="item.lectureOrder" :min="1" :max="100" :disabled="!writable" @update:value="changed"/></td><td><div class="p4-order-controls"><NButton :disabled="!writable||i===0" size="small" @click="move(i,-1)">上移</NButton><NButton :disabled="!writable||i===data.items.length-1" size="small" @click="move(i,1)">下移</NButton><NButton v-if="writable" size="small" @click="data.items.splice(i,1);changed()">移出</NButton></div></td></tr></tbody></table></div>
<p class="muted">预计难度由比赛管理者填写，在 Beamer 讲解前集中展示；可填等级或评分，最多 40 字，留空显示“未设置”。每道题开头会自动展示出题人设置的题目标签。</p>
<section class="contest-beamer-introduction" aria-labelledby="beamer-introduction-heading">
  <div class="contest-beamer-introduction-heading"><h3 id="beamer-introduction-heading">Beamer 开场总结（可选）</h3><NButton v-if="writable" size="small" :disabled="Boolean(data.beamerIntroduction?.trim())" @click="updateIntroduction(introductionExample)">填入示例</NButton></div>
  <p class="muted">在封面、难度概览之后，各题讲解之前插入。可提前编写比赛总结、题目安排或致谢，留空不生成；仅用于 Beamer 题解 PDF，随编排一起保存。</p>
  <p class="muted">填写完整的 LaTeX frame 页面，可写多页；主题由所选模板统一控制。最多 40,000 字。</p>
  <ContestIntroductionAssets :key="contest.id" :contest-id="contest.id" :writable="writable" @insert="insertIntroductionImage"/>
  <SourceEditor :model-value="data.beamerIntroduction??''" :readonly="!writable" @update:model-value="updateIntroduction"/>
  <div class="contest-introduction-count" :class="{'contest-introduction-error':introductionTooLong}">{{introductionLength.toLocaleString()}} / 40,000</div>
  <NAlert v-if="introductionTooLong" type="error">开场总结超过 40,000 字，请缩短后保存；当前内容仍保留在编辑器中。</NAlert>
</section>
<div class="p4-toolbar"><NButton type="primary" :loading="busy" :disabled="!writable||!dirty||introductionTooLong" @click="save">保存编排</NButton><NButton :disabled="contest.role!=='OWNER'||dirty||!data.items.length" @click="freeze">检查完整性并冻结</NButton><span class="muted">题目保存后自动同步，生成资料时固定当次内容。</span></div><NAlert v-if="syncError" type="warning">同步题目信息失败：{{syncError}}</NAlert><h3>最新题目内容的完整性</h3><table class="data-table"><thead><tr><th>题号与题目</th><th v-for="k in kinds" :key="k">{{kindLabels[k]}}</th></tr></thead><tbody><tr v-for="r in selectedItems" :key="r.problemId"><td>{{r.code}} · {{r.title}}</td><td v-for="k in kinds" :key="k"><NTag :type="r.materials[k]?'success':'warning'">{{r.materials[k]?'已提供':'缺稿或停用'}}</NTag></td></tr></tbody></table></div>
<template v-else-if="tab==='materials'"><div class="p4-toolbar"><NSelect v-model:value="revisionId" :options="[{label:'最新题目内容（自动同步）',value:'LATEST'},...contest.revisions.map((r:any)=>({label:`冻结 #${r.number}${r.current?' · 与最新内容一致':' · 历史清单'}`,value:r.id}))]" @update:value="subset=[]"/><NButton @click="refreshCurrent">刷新内容与任务</NButton><NCheckbox v-model:checked="useSubset">显式选择题目子集</NCheckbox><NSelect v-if="useSubset" v-model:value="subset" multiple :options="materialItems.map((i:any)=>({label:i.code+' · '+i.title,value:i.problemId}))" placeholder="选择完整稿件的题目"/></div><NAlert v-if="chosenFrozen&&!chosenFrozen.current" type="warning">当前选择的是历史冻结版本。要使用修改后的题目，请选择“最新题目内容（自动同步）”。</NAlert><div class="p4-toolbar"><NButton v-for="k in kinds" :key="k" :disabled="!writable||busy||dirty||(revisionId==='LATEST'&&!data.items.length)" @click="build([k])">生成{{kindLabels[k]}}{{k==='STATEMENT'?'题册':''}}</NButton><NButton type="primary" :disabled="!writable||busy||dirty||(revisionId==='LATEST'&&!data.items.length)" @click="build(['EDITORIAL_DOCUMENT','EDITORIAL_BEAMER'])">同时生成两种题解</NButton></div><NAlert v-if="missing.length" type="warning">缺少稿件：{{missing.map(m=>`${m.code} ${kindLabels[m.kind as DocumentKind]}`).join('；')}}。补齐或显式选取完整子集。</NAlert>
<div class="p4-build-grid"><aside class="p4-build-list"><template v-for="bundle in bundles" :key="bundle.id"><NTag :type="bundle.state==='PARTIAL_FAILED'?'warning':bundle.state==='SUCCEEDED'?'success':'default'">组合任务 · {{bundle.state}}</NTag><NButton v-for="b in bundle.builds" :key="b.id" :type="selectedBuild?.id===b.id?'primary':'default'" @click="inspect(b.id)">{{kindLabels[b.kind as DocumentKind]}} · {{b.state}}<br/>冻结 #{{b.input.contentVersion}} {{b.input.explicitSubset?' · 显式子集':''}} {{b.stale?' · 历史':''}}</NButton></template><NEmpty v-if="!bundles.length" description="尚无构建"/></aside><section v-if="selectedBuild"><div class="p4-toolbar"><NTag>{{selectedBuild.state}}</NTag><span class="muted">{{selectedBuild.id}}</span><NButton v-if="writable&&['QUEUED','RUNNING'].includes(selectedBuild.state)" @click="taskAction('cancel')">取消</NButton><NButton v-if="writable&&['FAILED','CANCELED'].includes(selectedBuild.state)" @click="taskAction('retry')">重试此子任务</NButton><NButton v-if="contest.role==='OWNER'" :disabled="selectedBuild.state!=='SUCCEEDED'||selectedBuild.stale||dirty" @click="publish">公开发布此 PDF</NButton></div><NTabs v-model:value="buildTab"><NTab name="preview">PDF 预览</NTab><NTab name="log">真实编译日志</NTab><NTab name="sources">固定来源</NTab></NTabs><PdfPreview v-if="buildTab==='preview'" :artifact-id="selectedBuild.artifacts[0]?.id"/><template v-else-if="buildTab==='log'"><NAlert v-if="selectedBuild.errorCode" type="error">{{selectedBuild.errorCode}}</NAlert><pre class="build-log">{{selectedBuild.log||'等待后台执行'}}</pre></template><div v-else><p>比赛冻结 {{selectedBuild.contestRevisionId}}<br/>模板 v{{selectedBuild.input.templateNumber}} · {{selectedBuild.input.templateHash}}</p><p v-for="e in selectedBuild.input.contest?.entries" :key="e.namespace">{{e.code}} · {{e.metadata.title}} · {{e.namespace}}</p><NAlert v-if="selectedBuild.input.explicitSubset" type="warning">此 PDF 仅包含以上显式选定的题目。</NAlert></div></section></div><h3>各类资料独立发布</h3><div v-for="r in releases" :key="r.id" class="publication-row"><NTag>{{kindLabels[r.purpose as DocumentKind]??r.purpose}}</NTag><span>{{r.revokedAt?'已撤回':'已发布'}}</span><a v-if="!r.revokedAt" :href="`/api/released/${r.token}/file`" target="_blank">下载该材料</a><NButton v-if="!r.revokedAt&&contest.role==='OWNER'" size="small" @click="revoke(r.id)">撤回</NButton></div></template>
<PackagePanel v-else-if="tab==='packages'" scope="contests" :id="contest.id" :owner="contest.role==='OWNER'" :has-unsaved="dirty"/><MemberPanel v-else scope="contests" :id="contest.id" :owner="contest.role==='OWNER'"/></div></template></template>

<style scoped>
.contest-items-scroll{overflow-x:auto}
.contest-difficulty-input{min-width:170px;max-width:240px}
.contest-beamer-introduction{margin:24px 0 16px;padding-top:12px;border-top:1px solid var(--line-soft)}
.contest-beamer-introduction-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}
.contest-beamer-introduction-heading h3{margin:0}
.contest-beamer-introduction :deep(.source-editor){height:300px;min-height:300px;border:1px solid var(--line-soft)}
.contest-introduction-count{text-align:right;margin-top:6px;color:var(--text-muted);font-size:12px}
.contest-introduction-error{color:var(--danger)}
</style>
